<script setup lang="ts">
import { onMounted, ref, shallowRef } from 'vue'
import R20ShadowMonitor from './R20ShadowMonitor.vue'
import { monitorSchema, type Monitor } from '../../r20-monitor-contract'
import { configRequest, configurationSchema, displayDecimal } from '../../r20-configuration-contract'
import type { Configuration } from '../../r20-configuration-contract'
import { useR20Preparation } from '../../stores/r20Preparation'
import type { PreparationField } from '../../r20-preparation-contract'
const props=withDefaults(defineProps<{admin?:boolean}>(),{admin:false})
const s=useR20Preparation()
const fields:{key:PreparationField,label:string,unit:string,hint:string}[]=[
 {key:'logical_capital_usd',label:'Capital lógico inicial',unit:'USD',hint:'Preparación de capital; no modifica un saldo existente.'},
 {key:'allocation_usd',label:'Capital asignado por operación',unit:'USD',hint:'Asignación solicitada. No es pérdida máxima.'},
 {key:'requested_allocation_leverage',label:'Apalancamiento sobre la asignación',unit:'×',hint:'Multiplicador objetivo; no es margen concedido por IBKR.'},
 {key:'risk_per_trade_pct',label:'Riesgo máximo por operación',unit:'%',hint:'Riesgo por precio. Costos y pérdida neta se muestran aparte.'},
 {key:'daily_loss_limit_pct',label:'Límite diario de pérdidas',unit:'%',hint:'Límite independiente sobre la referencia del día económico.'},
 {key:'max_open_positions',label:'Posiciones simultáneas máximas',unit:'posiciones',hint:'Cuenta posiciones y reservas pendientes.'}]
const monitor=shallowRef<Monitor|null>(null),monitorError=ref(''),monitorBusy=ref(false)
const legacy=shallowRef<Configuration|null>(null),legacyError=ref('')
async function loadMonitor(){if(monitorBusy.value)return;monitorBusy.value=true;try{monitor.value=monitorSchema.parse(await configRequest('shadow'));monitorError.value=''}catch{monitorError.value='SHADOW_READ_UNAVAILABLE'}finally{monitorBusy.value=false}}
async function loadLegacy(){try{legacy.value=configurationSchema.parse(await configRequest('configuration'));legacyError.value=''}catch{legacyError.value='Historial anterior no disponible'}}
const value=(v:string|null|undefined,unit='USD')=>v==null?'UNKNOWN':`${displayDecimal(v)} ${unit}`
onMounted(async()=>{await s.load();await s.calculate();loadMonitor()})
</script>
<template>
 <main class="r20-config">
  <header class="config-title"><div><p class="eyebrow">TRADINGAGENT / R20 V2</p><h1>Preparación económica</h1><p>Configura, revisa y guarda. La ejecución permanece bloqueada.</p></div><span class="badge">{{props.admin?'ADMINISTRADOR DE LABORATORIO':'SOLO LECTURA'}}</span></header>
  <aside class="test-notice"><strong>LABORATORIO AISLADO · SIN EJECUCIÓN</strong><p>Las configuraciones se guardan sólo en pruebas. Los escenarios de cálculo son sintéticos y no representan operaciones forward ni cargos confirmados por IBKR.</p></aside>
  <div class="safety-strip" aria-label="Seguridad y conectividad"><span>EmergencyStop <strong>{{s.state?.safety.emergency??'UNKNOWN'}}</strong></span><span>Live <strong>{{s.state?.safety.live??'UNKNOWN'}}</strong></span><span>Permiso Paper <strong>NO CONCEDIDO</strong></span><span>IBKR <strong>{{s.state?.safety.ibkr??'UNKNOWN'}}</strong></span></div>
  <p class="caption">{{s.state?.safety.observedAt?'Última evidencia de sólo lectura: '+s.state.safety.observedAt+' UTC. No es una conexión en tiempo real.':'Sin evidencia actual de conexión o emergencia. UNKNOWN no significa habilitado.'}}</p>
  <p v-if="s.error" role="alert" class="error">No se completó la solicitud: {{s.error}}. Última evidencia conservada como STALE; consulta el estado antes de reintentar.</p>
  <div class="status-row"><span class="badge">{{s.stale?'STALE':s.state?.status??'CARGANDO'}}</span><span class="badge">NO ACTIVADO</span><span v-if="s.state">{{s.state.day}} · America/Santo_Domingo · revisión {{s.state.revision}}</span><button :disabled="s.busy" @click="s.load">Actualizar estado</button></div>
  <div class="config-grid">
   <section class="card"><h2>1. Configuración del próximo perfil</h2><p>USD100, USD20 y20× son el ejemplo solicitado. Elige explícitamente riesgo, pérdida diaria y posiciones; ningún valor autoriza operaciones.</p>
    <form @submit.prevent="s.calculate">
     <div class="field-grid"><label v-for="field in fields" :key="field.key">{{field.label}} <span>({{field.unit}})</span><input v-model="s.values[field.key]" :name="field.key" :inputmode="field.key==='max_open_positions'?'numeric':'decimal'" autocomplete="off" :disabled="s.busy||!props.admin" :aria-label="field.label" :aria-describedby="field.key+'-hint'"/><small :id="field.key+'-hint'">{{field.hint}}</small></label></div>
     <label>Entorno solicitado <select v-model="s.values.environment" aria-label="Entorno solicitado" :disabled="s.busy||!props.admin"><option value="SHADOW">Shadow · preparación</option><option value="IBKR_PAPER">IBKR Paper · bloqueado</option></select></label>
     <label>Propósito del perfil <select v-model="s.purpose" aria-label="Propósito del perfil" :disabled="s.busy||!props.admin"><option value="NORMAL">NORMAL · exige target neto positivo</option><option value="TECHNICAL_VALIDATION">TECHNICAL_VALIDATION · sólo Shadow</option></select></label>
     <p v-if="s.purpose==='TECHNICAL_VALIDATION'" class="blockers">Ensayo técnico: puede admitir target neto negativo. Conserva riesgo, pérdidas diarias, margen y datos válidos. Necesita permiso Shadow separado; no acredita rentabilidad ni autoriza Paper.</p>
     <p v-if="s.values.environment==='IBKR_PAPER'" class="blockers">Paper bloqueado: adaptador, margen y permisos operativos pendientes. Esta selección sólo forma parte del borrador.</p><p v-else>Shadow bloqueado: todavía no existe un runner operativo autorizado.</p>
     <div class="actions"><button type="submit" :disabled="s.busy">Previsualizar y comprobar</button><button type="button" :disabled="!s.state?.latest||s.busy" @click="s.loadVersion()">Recuperar última versión</button></div>
    </form>
    <div class="workflow"><h3>Revisión explícita</h3><div class="actions"><button class="primary" :disabled="!props.admin||s.busy||s.stale||!s.state||!s.preview?.structurallyValid" @click="s.command('save')">Guardar configuración</button><button :disabled="!props.admin||s.busy||s.stale||!s.matchesSaved||s.state?.status!=='GUARDADO'" @click="s.command('validate')">Validar versión guardada</button></div><p>Guardar exige validación de campos en backend. VÁLIDO significa contrato estructural correcto; no habilita entradas.</p></div>
   </section>
   <section class="card"><h2>2. Exposición y restricciones</h2><p>Vista previa calculada en Python. El objetivo solicitado puede ser mayor que el tamaño admisible.</p>
    <dl><dt>Capital asignado solicitado</dt><dd>{{value(s.values.allocation_usd||null)}}</dd><dt>Multiplicador sobre asignación</dt><dd>{{value(s.values.requested_allocation_leverage||null,'×')}}</dd><dt>Exposición objetivo teórica</dt><dd data-testid="target">{{value(s.preview?.exposure_target_usd)}}</dd><dt>Objetivo / capital lógico inicial</dt><dd data-testid="target-leverage">{{value(s.preview?.target_account_leverage,'×')}}</dd><dt>Apalancamiento agregado actual</dt><dd>{{value(s.preview?.account_leverage,'×')}}</dd><dt>Cap agregado independiente</dt><dd>{{value(s.preview?.aggregate_leverage_cap,'×')}}</dd><dt>Exposición admisible (escenario)</dt><dd>{{value(s.preview?.assessment?.admitted?s.preview.assessment.exposure:null)}}</dd><dt>Margen requerido confirmado</dt><dd>{{value(s.preview?.confirmed_margin_usd)}}</dd></dl>
    <p class="caption">USD400 / USD100 =4× antes de costos, no20× de la cuenta. El apalancamiento agregado real requiere inventario y equity neto válidos.</p>
    <ul v-if="s.preview?.validationErrors.length" class="blockers" aria-label="Errores de configuración"><li v-for="r in s.preview.validationErrors" :key="r">{{r}}</li></ul>
    <ul v-if="s.preview?.unknowns.length" class="blockers" aria-label="Datos desconocidos"><li v-for="r in s.preview.unknowns" :key="r">{{r}}</li></ul>
    <template v-if="s.preview?.assessment"><p class="badge">{{s.preview.assessment.admitted?'ADMISIBLE SÓLO EN EL ESCENARIO SINTÉTICO':'ESCENARIO RECHAZADO'}}</p><ul class="blockers"><li v-for="r in s.preview.assessment.reasons" :key="r">{{r}}</li></ul>
     <dl v-if="s.preview.assessment.admitted"><dt>Cantidad EUR</dt><dd>{{value(s.preview.assessment.quantity,'EUR')}}</dd><dt>Riesgo por precio / presupuesto USD</dt><dd>{{s.preview.assessment.price_risk}} / {{s.preview.assessment.price_risk_budget}}</dd><dt>Margen inicial modelado</dt><dd>{{value(s.preview.assessment.initial_margin)}}</dd><dt>Apalancamiento agregado post-costos</dt><dd>{{value(s.preview.assessment.leverage_after_costs,'×')}}</dd><dt>Holgura / estrés USD</dt><dd>{{value(s.preview.assessment.headroom)}} / {{value(s.preview.assessment.required_headroom)}}</dd></dl>
    </template>
    <h3>Costos y resultado neto</h3><dl><dt>Costos estimados de ida/vuelta</dt><dd>{{value(s.preview?.assessment?.admitted?s.preview.assessment.estimated_costs:null)}}</dd><dt>Pérdida estimada al SL (USD)</dt><dd>{{value(s.preview?.assessment?.admitted?s.preview.assessment.net_stop:null)}}</dd><dt>Beneficio estimado al TP</dt><dd>{{value(s.preview?.assessment?.admitted?s.preview.assessment.net_target:null)}}</dd><dt>Comisiones del escenario</dt><dd>{{s.state?.costProvenance.commissions??'UNKNOWN'}}</dd><dt>Slippage / financiación</dt><dd>{{s.state?.costProvenance.slippage??'UNKNOWN'}} / {{s.state?.costProvenance.financing??'UNKNOWN'}}</dd></dl>
    <p>UNKNOWN no se sustituye por cero. Un target positivo no demuestra rentabilidad esperada. No hay cargos IBKR confirmados en esta preparación.</p>
   </section>
  </div>
  <section class="card controls"><div><h2>3. Preparación operativa</h2><p><strong>BLOQUEADO</strong> · Shadow y Paper requieren fases y autorizaciones posteriores.</p><p v-if="s.state?.status==='VALIDO'&&s.matchesSaved" class="badge">LISTO PARA REVISIÓN · NO ACTIVADO</p><p>Iniciar, detener o cambiar entorno todavía no dispone de backend operativo autorizado. Guardar no concede permisos.</p></div><div class="actions"><button disabled title="Runner operativo no autorizado">Iniciar</button><button disabled title="No hay runner operativo controlable">Detener</button><button disabled title="Transición de entorno no implementada">Cambiar entorno</button></div></section>
  <section class="card history-card"><h2>Historial de configuraciones</h2><p v-if="!s.state?.history.length">Todavía no hay versiones de preparación guardadas.</p><ol class="history"><li v-for="item in [...(s.state?.history??[])].reverse()" :key="item.revision"><div><strong>Versión {{item.profile.configuration_version}} · {{item.lifecycle}} · {{item.profile.values.environment}}</strong><p>{{item.actor}} · {{item.at}} UTC<br>Vigencia: {{item.profile.effective_from}} → {{item.profile.effective_until}} UTC</p><code>{{item.profile.profile_id}}<br>Perfil {{item.profile.configuration_hash}}<br>Evento {{item.hash}}</code></div><button :disabled="s.busy" @click="s.loadVersion(item.revision)">Cargar revisión {{item.revision}}</button></li></ol>
   <details @toggle="loadLegacy"><summary>Historial anterior del laboratorio · sólo lectura</summary><p v-if="legacyError">{{legacyError}}</p><p v-if="legacy&&!legacy.history.length">Sin versiones anteriores en este ámbito de pruebas.</p><p v-for="item in legacy?.history??[]" :key="item.revision" class="hash">Revisión {{item.revision}} · {{item.lifecycle}} · {{item.hash}}</p></details>
  </section>
  <details class="card"><summary>Seguimiento Shadow del laboratorio</summary><button :disabled="monitorBusy" @click="loadMonitor">Actualizar seguimiento Shadow</button><R20ShadowMonitor :snapshot="monitor" :error="monitorError"/></details>
 </main>
</template>
<style scoped>
.r20-config{max-width:1360px;margin:auto;padding:32px;color:#dce7ed;font:15px/1.55 system-ui,sans-serif}.config-title,.status-row,.actions,.controls{display:flex;gap:16px;align-items:center;flex-wrap:wrap}.config-title,.controls{justify-content:space-between;margin-bottom:24px}.eyebrow{color:#65d8c7;font-size:12px;letter-spacing:.14em}h1{font-size:32px;line-height:1.2;margin:8px 0}h2{font-size:20px;margin:0 0 12px}h3{font-size:16px;margin:22px 0 10px}p{color:#b5c8d2;margin:8px 0 18px}.badge{display:inline-block;border:1px solid #537380;border-radius:6px;padding:7px 10px;font-size:12px;color:#a3eadd;overflow-wrap:anywhere}.test-notice{background:#253025;border:1px solid #75804b;border-radius:10px;padding:18px;margin-bottom:20px}.test-notice strong{color:#e0d793;font-size:13px}.test-notice p{margin:8px 0 0;color:#d1d4bc}.safety-strip{display:flex;gap:18px;flex-wrap:wrap;padding:14px 0;border-bottom:1px solid #36505f;font-size:13px}.safety-strip strong{display:block;color:#efd799}.caption{font-size:12px;color:#acc3cf}.status-row{margin:20px 0}.config-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:20px}.card{background:#13242e;border:1px solid #36515f;border-radius:12px;padding:24px;min-width:0}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:22px 0}label{display:block;color:#d5e6ed;font-size:14px}label span,small{color:#abc1cd}small{display:block;margin-top:6px;font-size:12px}input,select{display:block;box-sizing:border-box;width:100%;margin-top:8px;background:#0b1a23;border:1px solid #638390;border-radius:6px;padding:12px;color:white;font:inherit}input:focus,select:focus,button:focus-visible,summary:focus-visible{outline:3px solid #5de1ca;outline-offset:3px}button{cursor:pointer;background:#243e4b;border:1px solid #60818f;border-radius:6px;color:#e1eff4;padding:11px 14px;font:inherit;font-size:14px}button.primary{background:#14665d;border-color:#54cbb7}button:disabled{opacity:.55;cursor:not-allowed}.workflow{border-top:1px solid #3d5969;margin-top:22px}.workflow p{font-size:13px;margin-top:14px}.blockers,.error{color:#ffbea9;overflow-wrap:anywhere}.error{padding:16px;background:#452b2b}dl{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:12px 18px}dt{color:#aec5d1}dd{margin:0;text-align:right;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.hash,code{font-size:12px;overflow-wrap:anywhere;color:#abd6ce}.history-card{margin-bottom:20px}.history{list-style:none;padding:0;margin:0}.history li{display:flex;justify-content:space-between;gap:16px;align-items:start;border-top:1px solid #3d5969;padding:18px 0}.history li>div{min-width:0}.history p{font-size:13px;margin-bottom:8px}.history button{flex-shrink:0}summary{cursor:pointer;font-weight:600;padding:8px 0}details>button{margin:16px 0}.controls>div:first-child{max-width:720px}@media(max-width:760px){.r20-config{padding:18px 14px}.config-grid,.field-grid{grid-template-columns:1fr}.card{padding:18px}h1{font-size:27px}.actions{gap:10px;width:100%}.actions button{flex:1 1 140px}.status-row{font-size:13px}dl{gap:12px;font-size:13px}.badge{max-width:100%}.history li{display:block}.history button{margin-top:12px}.safety-strip>span{flex:1 1 40%}}
</style>
